import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../../axiosService/ApiCall";
import { ToastContainer, toast } from "react-toastify";
import { Modal, Button } from "react-bootstrap";
import Select from "react-select";
import { MdRefresh } from "react-icons/md";
import { decryptData } from "../../Auth/SecurityCrypto";
import axios from "axios";

function SubminPage() {
  const [data, setData] = useState([]);
  const [totalRows, setTotalRows] = useState(null);
  const [limit, setLimit] = useState(10);
  // console.log("limit", limit);
  const [currentPage, setCurrentPage] = useState(1);
  // console.log("currentPage", currentPage);
  // delete modal state.........
  const [showModal, setShowModal] = useState(false);
  const [selectedId, setSelectedId] = useState(null);
  const [adminActiveStatus, setadminActiveStatus] = useState("");
  const [adminType, setAdminType] = useState("");
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState(null);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // fetchData with page param
  const fetchData = async (page = 1) => {
    let url = `get-subAdmin?page=${page}&limit=${limit}`;

    // search filter add
    if (search) {
      url += `&search=${search}`;
    }

    // status filter add
    if (status) {
      url += `&status=${status.value}`;
    }
    try {
      const params = {
        url,
        //url: `get-subAdmin?page=${page}&limit=${limit}`,
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };

      const getSubadmindata = await makeApiRequest(params);
      // console.log("getSubadmindata", getSubadmindata);

      if (getSubadmindata && getSubadmindata.status) {
        // Add a serial number to each item so S.No stays correct across pages
        const startIndex = (page - 1) * limit;
        const withSerial = (getSubadmindata.data || []).map((item, idx) => ({
          ...item,
          _serial: startIndex + idx + 1,
        }));

        setData(withSerial);
        setTotalRows(getSubadmindata.total || 0);
        setCurrentPage(page || 1);
        setLimit(getSubadmindata.limit || 10);
      } else {
        toast.error("Failed to fetch data");
      }
    } catch (error) {
      console.error("fetchData error:", error);
      // toast.error("Error fetching data");
    } finally {
      // setLoading(false);
    }
  };

  // initial load
  useEffect(() => {
    fetchData(currentPage);
  }, [currentPage, limit]);
  useEffect(() => {
    setCurrentPage(1);
    fetchData(1);
  }, [search, status]);
  // ............ active and deactive status...................

  const handleStatusChange = async (id, newStatus) => {
    try {
      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;
      const params = {
        url: `admin-activestatus/${id}`, // particular sub admin id
        method: "POST",
        data: {
          activestatus: newStatus, // Active or Inactive
          ip: lastloginIpAddress,
        },
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };

      const activestatusEncryptRes = await makeApiRequest(params);
      // console.log("activestatusEncryptRes:", activestatusEncryptRes);
      const activeStatusDecryptRes = await decryptData(
        activestatusEncryptRes.data
      );
      // console.log(activeStatusDecryptRes, "activeStatusDecryptRes");

      if (activeStatusDecryptRes && activeStatusDecryptRes.status == true) {
        toast.success(activeStatusDecryptRes.message);
        fetchData(currentPage); // data refresh
      } else {
        toast.error(activeStatusDecryptRes.message);
      }
    } catch (error) {
      console.error("Status update error:", error);
      // toast.error("Error updating status");
    }
  };

  // ............ active and deactive status finsihed ...................

  // columns: use the _serial we attached
  const columns = [
    {
      name: "S.No",
      selector: (row) => row._serial ?? "-",
      width: "90px",
    },
    {
      name: "Admin Name",
      selector: (row) => row.adminName || "-",
      sortable: true,
    },
    {
      name: "Email Address",
      selector: (row) => row.email || "-",
      sortable: true,
    },

    {
      name: "ActiveStatus",
      cell: (row) => (
        <div style={{ marginBottom: "16px" }}>
          <select
            value={row.active_status || ""}
            onChange={(e) => handleStatusChange(row._id, e.target.value)} // அந்த row id + value
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "14px",
            }}
          >
            {/* <option value="">Select Your Status</option>  */}
            <option value="Active">Active</option>
            <option value="Inactive">Inactive</option>
          </select>
        </div>
      ),
    },
    {
      name: "Action",
      cell: (row) => (
        <div className="d-flex gap-3">
          <Link to={`/dashboard/edit-subadmin/${row._id}`}>
            <button className="custom-nav-button-1 active mb-3 pr-3">
              Edit
            </button>
          </Link>
          <button
            className="custom-nav-button-1 active mb-3"
            onClick={() => openDeleteModal(row._id)}
          >
            Delete
          </button>
        </div>
      ),
    },
  ];

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };

  // when page changes (pagination)
  const handlePageChange = (page) => {
    fetchData(page);
  };

  // rows-per-page changed by user
  const handlePerRowsChange = (newPerPage, page) => {
    setLimit(newPerPage);
    setCurrentPage(1);
  };
  // delete functionality
  const openDeleteModal = (id) => {
    setSelectedId(id);
    setShowModal(true);
  };

  // close modal
  const handleClose = () => {
    setShowModal(false);
    setSelectedId(null);
  };
  const handleDeleteConfirm = async () => {
    try {
      const address = await axios.get("https://api.ipify.org/?format=json");
      const lastloginIpAddress = address.data.ip;
      // console.log("lastloginIpAddress", lastloginIpAddress);
      //  return;
      const ipaddress = lastloginIpAddress;

      const params = {
        url: `delete-subAdmin/${selectedId}`,
        method: "POST",
        data: {
          ip: ipaddress,
        },
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      // console.log("params:", params.data);

      const response = await makeApiRequest(params);
      // console.log("delete response:", response);

      if (response && response.status) {
        toast.success("Sub Admin deleted successfully!");
        handleClose();
        fetchData(currentPage); // refresh current page
      } else {
        toast.error("Failed to delete Sub Admin");
      }
    } catch (error) {
      console.error("Delete error:", error);
      toast.error("An error occurred while deleting Sub Admin");
    }
  };

  useEffect(() => {
    adminTypeResData();
  }, []);
  const adminTypeResData = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const adminTypeResData = await makeApiRequest(params);
      // console.log("adminTypeResData>>>", adminTypeResData);
      if (adminTypeResData.status) {
        const response = adminTypeResData.data.adminPermissions;
        setAdminType(adminTypeResData.data.admin_type);
      }
    } catch (error) {
      console.log("err", error);
      // toast("Something Went Wrong...");
    }
  };
  const statusOptions = [
    { value: "Active", label: "Active" },
    { value: "Inactive", label: "Inactive" },
  ];
  const handleClearFilters = () => {
    setIsRefreshing(true);
    setSearch("");
    setStatus("");
    setTimeout(() => {
      setIsRefreshing(false);
    }, 500);
  };

  return adminType == "SuperAdmin" ? (
    <div className="App">
      <ToastContainer />
      <div className="container-fluid">
        <div className="custom-saled-order">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  Sub Admin List
                </h3>
                <Link to="/dashboard/new-subadmin">
                  <button className="custom-nav-button-1 active mb-3">
                    Add New Sub Admin
                  </button>
                </Link>
              </div>
              <div className="row">
                <div className="d-flex calendor-form align-items-end gap-4 flex-wrap">
                  {/* Search Input */}
                  <div>
                    <label htmlFor="email" className="form-label">
                      Email
                    </label>
                    <input
                      type="text"
                      placeholder="email or name"
                      className="form-control search-bar"
                      value={search}
                      onChange={(e) => setSearch(e.target.value)}
                    // value={searchQuery}
                    // onChange={handleSearchChange}
                    />
                  </div>

                  {/* Currency Dropdown */}
                  <div style={{ minWidth: "250px" }}>
                    <label htmlFor="currency" className="form-label">
                      Status
                    </label>
                    <Select
                      className=" w-100"
                      id="currency"
                      options={statusOptions}
                      value={status}
                      onChange={(val) => setStatus(val)}
                      isClearable
                      styles={customStyles}
                    // onChange={handleChange}
                    />
                  </div>
                  <div>
                    <button
                      type="button"
                      className="custom-nav-button-1 active cursor-pointer"
                      onClick={handleClearFilters}
                      disabled={isRefreshing}
                    >
                      <MdRefresh
                        style={{ fontSize: "24px" }}
                        className={isRefreshing ? "rotate-icon" : ""}
                      />
                    </button>
                  </div>
                </div>

                {/* Table Section */}
                <div className="mt-3 liquidity-table-1">
                  <DataTable
                    columns={columns}
                    data={data}
                    pagination
                    paginationServer
                    paginationTotalRows={totalRows}
                    onChangeRowsPerPage={handlePerRowsChange}
                    onChangePage={handlePageChange}
                    paginationPerPage={limit}
                    paginationRowsPerPageOptions={[5, 10, 15]}
                    paginationDefaultPage={currentPage}
                    highlightOnHover
                    persistTableHead
                    noHeader={false}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
        <Modal
          show={showModal}
          onHide={handleClose}
          backdrop="static"
          keyboard={false}
          centered
        >
          <Modal.Header closeButton>
            <Modal.Title>Confirm Delete</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            Are you sure you want to delete this Sub Admin?
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleClose}>
              Cancel
            </Button>
            <Button variant="danger" onClick={handleDeleteConfirm}>
              Delete
            </Button>
          </Modal.Footer>
        </Modal>
      </div>
    </div>
  ) : null;
}

export default SubminPage;
